import React from 'react';
import { Container, Card, CardContent, Typography, Button, Box } from '@mui/material';
import EcoIcon from '@mui/icons-material/Eco';
import AirIcon from '@mui/icons-material/Air';
import HealthAndSafetyIcon from '@mui/icons-material/HealthAndSafety';
import { useNavigate } from 'react-router-dom';

function Home() {
  const navigate = useNavigate();
  return (
    <Box
      sx={{
        minHeight: '80vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        background: 'linear-gradient(135deg, #e8f5e9 0%, #b2dfdb 100%)',
      }}
    >
      <Container maxWidth="md">
        <Card sx={{
          p: 4,
          borderRadius: 6,
          boxShadow: '0 8px 32px 0 rgba(67,160,71,0.15)',
          background: 'linear-gradient(120deg, #ffffff 60%, #e0f2f1 100%)',
        }}>
          <CardContent sx={{ textAlign: 'center' }}>
            <EcoIcon sx={{ fontSize: 64, color: 'primary.main', mb: 1 }} />
            <AirIcon sx={{ fontSize: 48, color: 'secondary.main', ml: 2, mr: 2, mb: 1 }} />
            <HealthAndSafetyIcon sx={{ fontSize: 48, color: 'success.main', mb: 1 }} />
            <Typography variant="h3" fontWeight={700} gutterBottom sx={{ mt: 2 }}>
              Welcome to Air Quality Predictor
            </Typography>
            <Typography variant="h6" color="text.secondary" sx={{ mb: 3 }}>
              🌱 Breathe easy. Predict, monitor, and improve your air quality for a healthier life.
            </Typography>
            <Typography variant="body1" sx={{ mb: 4 }}>
              Enter any city or coordinates to instantly get air quality predictions, health recommendations, and beautiful visualizations. Powered by AI and real-time data.
            </Typography>
            <Button
              variant="contained"
              color="primary"
              size="large"
              sx={{ px: 5, py: 1.5, fontSize: 20, borderRadius: 8, boxShadow: 2 }}
              onClick={() => navigate('/input')}
            >
              Get Started
            </Button>
          </CardContent>
        </Card>
      </Container>
    </Box>
  );
}

export default Home;
